def transform(grid):
    bg = grid[0][0]
    markers = []
    rows, cols = len(grid), len(grid[0])

    # Find marker positions
    for r in range(rows):
        for c in range(cols):
            if grid[r][c] != bg:
                markers.append((r, c))

    result = [[0]*cols for _ in range(rows)]

    for r in range(rows):
        for c in range(cols):
            if grid[r][c] == bg:
                # Convert to 3 if close to markers (Manhattan distance <= 2)
                min_dist = min(abs(r - mr) + abs(c - mc) for mr, mc in markers)
                result[r][c] = 3 if min_dist <= 2 else bg
            else:
                result[r][c] = grid[r][c]

    return result
